// No compiler check exists here: the default arm is the only safety net.
switch (event.type) {
  case 'click': {
    const { x, y } = event;            // destructuring binds the payload
    move(x, y);
    break;
  }
  case 'key':
    handleKey(event.rune);
    break;
  default:
    throw new Error(`unhandled event: ${event.type}`);
}
